"""Portable vectors generated by compiled primary Go serialization, not a model."""
import hashlib
import json
from pathlib import Path
import unittest

from common import json_bytes
from proxy import identity, input_root, validate_request

EXPECTED_SHA256 = "47acfc863322341910ee3fba62bcbe5fcddd67c1d51af74522f4aa8081323076"


def checked_fixture(raw):
    if hashlib.sha256(raw).hexdigest() != EXPECTED_SHA256:
        raise ValueError("compiled primary input fixture changed")
    value = json.loads(raw)
    if (value["kind"] != "compiled-primary-input-serialization-fixture" or value["model_operations"] is not False
            or value["reference_engine_vectors"] is not False or len(value["vectors"]) != 12):
        raise ValueError("input-root fixture is not source-only primary serialization")
    return value


class PrimaryInputRootTests(unittest.TestCase):
    def setUp(self):
        self.raw = (Path(__file__).parent / "primary-input-roots.json").read_bytes()
        self.fixture = checked_fixture(self.raw)

    def test_all_actual_primary_go_input_roots_match(self):
        for vector in self.fixture["vectors"]:
            with self.subTest(count=len(vector["batch_tokens"])):
                self.assertEqual(input_root([{"tokens": ids} for ids in vector["batch_tokens"]]), vector["input_root"])

    def test_exact_canonical_json_bytes_not_normalized(self):
        for vector in self.fixture["vectors"]:
            for ids, encoded in zip(vector["batch_tokens"], vector["canonical_inputs"]):
                actual = json_bytes({"input_ids": ids, "attention_mask": [1] * len(ids)}).decode()
                self.assertEqual(actual, encoded)
                wrong = json.dumps({"input_ids": ids, "attention_mask": [1] * len(ids)}, sort_keys=True, separators=(",", ":"))
                self.assertNotEqual(wrong, encoded)

    def test_fixture_tampering_can_fail(self):
        changed = self.fixture.copy()
        changed["source_revision"] = "0" * 40
        with self.assertRaises(ValueError):
            checked_fixture(json.dumps(changed).encode())

    def test_serializer_vectors_do_not_authorize_invalid_tokens(self):
        row = {"keccak": "a" * 64, "runnable_url": "https://tga1.zkasuran.dev/_sourceprobe/runnable"}
        for tokens in ([], [-1], [50368], [True]):
            with self.subTest(tokens=tokens), self.assertRaises(ValueError):
                validate_request({"batch": [{"tokens": tokens}], **identity(row)}, row)


if __name__ == "__main__":
    unittest.main()
